// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Seed the market with some drugs to make initialized true
        c.seedMarket(100);
        // Create two users: Alice and Bob
        address alice = address(0x1111);
        address bob = address(0x2222);
        // Give Alice some ether to buy drugs
        vm.deal(alice, 1 ether);
        // Alice buys drugs to have claimedDrugs for later
        vm.prank(alice);
        c.buyDrugs{value: 0.1 ether}();
        // Bob calls getFreeKilo() (warp to set block.timestamp)
        vm.warp(1000);
        vm.prank(bob);
        c.getFreeKilo();
        // Now Alice calls collectDrugs with bob as ref, which reads bob's lastCollect via getDrugsSinceLastCollect
        vm.prank(alice);
        c.collectDrugs(bob);
        // At this point, in reference, bob's lastCollect = 1000 (set by getFreeKilo), so getDrugsSinceLastCollect(bob) = min(86400, 1000-1000)*Kilos[bob] = 0
        // In mutant, bob's lastCollect = 0 (never set), so getDrugsSinceLastCollect(bob) = min(86400, 1000-0)*Kilos[bob] = 1000 * 300 = 300000
        // Therefore getMyDrugs() for bob differs (claimedDrugs maybe 0 initially)
        uint256 refValue = c.getMyDrugs();
        // We assert that the result is exactly as in reference (0, because lastCollect was set)
        assertTrue(refValue == 0, "In reference, bob's getMyDrugs should be 0; mutant gives non-zero");
    }
}

