pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call seedMarket with 1000 drugs (any positive number works)
        c.seedMarket(1000);
        // After seedMarket, get marketDrugs
        uint256 marketDrugs = c.marketDrugs();
        // Reference: marketDrugs = 1000, Bug: marketDrugs = 0
        // Use calculateDrugSell(1) which depends on marketDrugs
        uint256 sellValue = c.calculateDrugSell(1);
        // In reference, marketDrugs=1000 yields a different sellValue than bug (marketDrugs=0)
        // We assert the value matches the reference behavior (marketDrugs=1000)
        // Specifically, compute expected: calculateTrade(1, 1000, contractBalance)
        // contractBalance is 0 (no ETH sent yet), so the formula yields 0
        assertTrue(sellValue == 0, "Bug: calculateDrugSell(1) should be 0 for reference with no ETH");
    }
}

