import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x123);
        // Seed market with 10000 drugs so buyDrugs can work
        vm.deal(address(this), 1 ether);
        c.seedMarket(10000);
        // Now buy drugs with 0.1 ether
        vm.deal(user, 0.1 ether);
        vm.prank(user);
        c.buyDrugs{value: 0.1 ether}();
        // Reference: drugsBought = calculateDrugBuy(0.1 ether, 0.1 ether, 10000) = 1040
        // devFee = 4% of 1040 = 41.6 -> truncated to 41
        // drugsBought = 1040 - 41 = 999? actually compute precisely:
        // calculateDrugBuy(0.1e18, 0.1e18, 10000) = (PSN * marketDrugs * eth) / (PSNH * (eth + contractBalance) + PSN * contractBalance)
        // = (10000 * 10000 * 0.1e18) / (5000 * (0.1e18 + 0.1e18) + 10000 * 0.1e18) = 1e25 / (1e21 + 1e21) = 1e25 / 2e21 = 5000
        // Actually recalc: eth = 0.1e18, contractBalance = 0.1e18, marketDrugs=10000
        // numerator = 10000 * 10000 = 1e8, multiply by 0.1e18 = 1e25
        // denominator PSNH*(eth+contractBalance) = 5000 * 0.2e18 = 1e21, plus PSN*contractBalance = 10000 * 0.1e18 = 1e21, total = 2e21
        // drugsBought = 1e25 / 2e21 = 5000
        // devFee = 4% of 5000 = 200
        // reference: drugsBought = 5000 - 200 = 4800
        // bug: drugsBought = 5000 + 200 = 5200
        // difference in claimedDrugs[user] = 4800 vs 5200
        assert(c.claimedDrugs(user) == 4800, "claimed drugs should be 4800 wei (reference subtracts fee)");
    }
}

