        vm.deal(address(this), 10 ether);
        c.seedMarket{value: 1 ether}(1000000);

        // User gets free kilos
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.getFreeKilo();

        // Warp time to accumulate drugs (86401 seconds to produce just over 1 kilo worth)
        vm.warp(block.timestamp + 86401);

        // User collects drugs (converts accumulated drugs to kilos, resets claimedDrugs)
        vm.prank(user);
        c.collectDrugs(address(0));

        // Now user buys drugs with exactly 1 ether
        // At this point contract balance = 1 ether (from seedMarket) + 1 ether (from this tx) but sub of msg.value in buyDrugs
        vm.prank(user);
        c.buyDrugs{value: 1 ether}();

        // Reference subtracts devFee(960) from drugsBought (calculated as ~1000) => claimedDrugs ~1000 - 40 = 960
        // Bug adds devFee(960) to drugsBought => claimedDrugs ~1000 + 40 = 1040
        uint256 claimed = c.claimedDrugs(user);
        assert(claimed == 960 || claimed == 1040, "claimed should be 960 (reference) or 1040 (bug)");
        // For the test to pass on reference and fail on bug, we assert reference holds
        assert(claimed == 960, "claimed drugs should be 960 (reference subtracts fee)");
    }
}

