pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Call DrugDealer() to set ceoAddress to test contract (this)
        address deployer = address(this);
        vm.prank(deployer);
        c.DrugDealer();

        // Step 2: Seed marketDrugs with 0 (initialization)
        c.seedMarket(0);

        // Step 3: Fund contract with some ether so balance > 0 before buy
        vm.deal(address(c), 2 ether);

        // Step 4: Call buyDrugs with 1 ether from a user
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.buyDrugs{value: 1 ether}();

        // Step 5: Read claimedDrugs[user] from contract
        uint256 claimed = c.claimedDrugs(user);

        // The reference uses SafeMath.sub(address(this).balance, msg.value) which is 2 ether - 1 ether = 1 ether
        // The bug uses SafeMath.add(address(this).balance, msg.value) which is 2 ether + 1 ether = 3 ether
        // Since the bug produces a much larger drugsBought, claimedDrugs[user] will be larger
        // The reference produces a smaller value; we assert that claimed is less than some threshold
